 * Flat dependency resolution over an in-memory registry: one version per
 * package, chosen highest-first, with a conflict report naming the chain that
 * imposed each constraint.
 */
import { ResolveError, compareVersions, parseRange, parseVersion, satisfies } from './semver.js';

/** Raised when no version of a package satisfies everything asked of it. */
export class ConflictError extends ResolveError {
  /**
   * @param {string} packageName Package that could not be satisfied.
   * @param {Array<{range: string, via: string}>} constraints Every constraint on it, in the order they arrived.
   * @param {string[]} available Versions the registry offers, ascending.
   */
  constructor(packageName, constraints, available) {
    const detail = constraints.map((entry) => `${entry.range} (from ${entry.via})`).join(', ');
    super('CONFLICT', `cannot satisfy ${packageName}: ${detail}`);
    this.name = 'ConflictError';
    this.packageName = packageName;
    this.constraints = constraints;
    this.available = available;
  }
}

/**
 * True for plain objects (not null, not arrays).
 *
 * @param {unknown} value Value to test.
 * @returns {boolean} Whether it is a usable map.
 */
function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Validate the registry shape and every range inside it.
 *
 * @param {unknown} registry Registry to check.
 * @returns {void}
 */
function validateRegistry(registry) {
  if (!isPlainObject(registry)) throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  for (const [name, entry] of Object.entries(registry)) {
    if (!isPlainObject(entry)) throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    for (const [version, metadata] of Object.entries(entry)) {
      parseVersion(version);
      if (!isPlainObject(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${version}`);
      }
      const deps = metadata.deps;
      if (deps === undefined) continue;
      if (!isPlainObject(deps)) {
        throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${version} must be an object`);
      }
      for (const range of Object.values(deps)) parseRange(range);
    }
  }
}

/**
 * Versions a registry entry offers, in ascending order.
 *
 * @param {Record<string, unknown>} entry Registry entry.
 * @returns {string[]} Ascending versions.
 */
function ascendingVersions(entry) {
  return Object.keys(entry).sort(compareVersions);
}

/**
 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
export function resolve(registry, rootDeps) {
  validateRegistry(registry);
  if (!isPlainObject(rootDeps)) throw new ResolveError('BAD_DEPENDENCIES', 'root dependencies must be an object');
  for (const range of Object.values(rootDeps)) parseRange(range);

  /** @type {Map<string, Array<{range: string, via: string}>>} */
  const constraints = new Map();
  /** @type {Set<string>} */
  const pending = new Set();
  /** @type {Map<string, string>} */
  const selected = new Map();
  const order = [];

  const record = (name, range, via) => {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push({ range, via });
  };

  for (const name of Object.keys(rootDeps).sort()) {
    record(name, rootDeps[name], '<root>');
    pending.add(name);
  }

  while (pending.size > 0) {
    const name = [...pending].sort()[0];
    pending.delete(name);
    const entry = registry[name];
    if (entry === undefined) throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    const available = ascendingVersions(entry);
    const list = constraints.get(name) ?? [];
    const candidates = available.filter((version) => list.every((item) => satisfies(version, item.range)));
    if (candidates.length === 0) throw new ConflictError(name, list, available);
    const choice = candidates[candidates.length - 1];
    selected.set(name, choice);
    order.push(name);
    const origin = list.length > 0 ? list[0].via : '<root>';
    const chain = `${origin} > ${name}@${choice}`;

    const deps = entry[choice].deps ?? {};
    for (const depName of Object.keys(deps).sort()) {
      const range = deps[depName];
      record(depName, range, chain);
      if (!selected.has(depName)) {
        pending.add(depName);
      } else if (!satisfies(selected.get(depName), range)) {
        throw new ConflictError(depName, constraints.get(depName), ascendingVersions(registry[depName]));
      }
    }
  }

  const resolved = {};
  for (const name of [...selected.keys()].sort()) resolved[name] = selected.get(name);
  return { resolved, order };
}
