{"file_path":"src/patch.js","content":"/** JSON Patch application with all-or-nothing semantics. */

import { PointerError, formatPointer, parsePointer, resolve } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

/** @param {unknown} value @returns {string} a human name for the JSON type of `value` */
function typeName(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

/** @param {unknown} value @returns {boolean} whether `value` is representable as JSON data */
function isJSON(value) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'boolean' || type === 'string') return true;
  if (type === 'number') return Number.isFinite(value);
  if (Array.isArray(value)) return value.every(isJSON);
  if (type === 'object') {
    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) return false;
    return Object.keys(value).every((key) => isJSON(value[key]));
  }
  return false;
}

/**
 * Deep clone JSON data, treating every own enumerable key (including ones that
 * shadow `Object.prototype`, such as `__proto__`) as an ordinary property.
 *
 * @param {unknown} value JSON data to clone
 * @returns {unknown} an independent deep copy
 */
function cloneJSON(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(cloneJSON);
  const result = {};
  for (const key of Object.keys(value)) setProp(result, key, cloneJSON(value[key]));
  return result;
}

/**
 * Validate that `value` is JSON data and return an independent deep copy.
 *
 * @param {unknown} value candidate JSON data
 * @param {string} kind name used in the error message when it is not JSON data
 * @returns {unknown} an independent deep copy
 */
function cloneChecked(value, kind) {
  if (!isJSON(value)) throw new Error(`${kind} is not JSON data`);
  return cloneJSON(value);
}

/**
 * Set an own data property, bypassing any inherited accessor (such as the
 * `__proto__` accessor on `Object.prototype`).
 *
 * @param {object} target object to modify
 * @param {string} key property name
 * @param {unknown} value property value
 */
function setProp(target, key, value) {
  Object.defineProperty(target, key, { value, writable: true, enumerable: true, configurable: true });
}

/**
 * Compare two JSON values structurally: object members in any order, array
 * elements in order, and no type coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether they are structurally equal as JSON
 */
function jsonEqual(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((item, i) => jsonEqual(item, b[i]));
  }
  if (a !== null && b !== null && typeof a === 'object' && typeof b === 'object') {
    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) return false;
    return aKeys.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEqual(a[key], b[key]));
  }
  return false;
}

/**
 * Validate an index token against an array, allowing the `-` append token and
 * an index equal to the array's length only when `allowAppend` is set.
 *
 * @param {string} token the raw last token
 * @param {unknown[]} array the array it indexes into
 * @param {string} pointer the full pointer, for error messages
 * @param {boolean} allowAppend whether `token === array.length` (or `-`) is valid
 * @returns {number} the resolved index
 */
function arrayIndex(token, array, pointer, allowAppend) {
  if (token === '-') {
    if (allowAppend) return array.length;
    throw new PointerError(`invalid array index: - at ${pointer}`, pointer);
  }
  if (!/^(0|[1-9]\d*)$/.test(token)) throw new PointerError(`invalid array index: ${token} at ${pointer}`, pointer);
  const index = Number(token);
  const limit = allowAppend ? array.length : array.length - 1;
  if (index > limit) throw new PointerError(`index out of range: ${index} at ${pointer}`, pointer);
  return index;
}

/** Apply `add`, mutating `document` in place and returning it (or a replacement whole document). */
function doAdd(document, path, rawValue) {
  const value = cloneChecked(rawValue, 'value');
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  const parent = resolve(document, formatPointer(tokens.slice(0, -1)));
  const lastToken = tokens[tokens.length - 1];
  if (Array.isArray(parent)) {
    parent.splice(arrayIndex(lastToken, parent, path, true), 0, value);
  } else if (parent !== null && typeof parent === 'object') {
    setProp(parent, lastToken, value);
  } else {
    throw new PointerError(`cannot index into ${typeName(parent)} at ${path}`, path);
  }
  return document;
}

/** Apply `remove`, mutating `document` in place and returning it. */
function doRemove(document, path) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) throw new Error('cannot remove the whole document');
  resolve(document, path);
  const parent = resolve(document, formatPointer(tokens.slice(0, -1)));
  const lastToken = tokens[tokens.length - 1];
  if (Array.isArray(parent)) parent.splice(Number(lastToken), 1);
  else delete parent[lastToken];
  return document;
}

/** Apply `replace`, mutating `document` in place and returning it (or a replacement whole document). */
function doReplace(document, path, rawValue) {
  const value = cloneChecked(rawValue, 'value');
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  resolve(document, path);
  const parent = resolve(document, formatPointer(tokens.slice(0, -1)));
  const lastToken = tokens[tokens.length - 1];
  if (Array.isArray(parent)) parent[Number(lastToken)] = value;
  else setProp(parent, lastToken, value);
  return document;
}

/** Apply `move`, mutating `document` in place and returning it. */
function doMove(document, path, from) {
  const fromTokens = parsePointer(from);
  const pathTokens = parsePointer(path);
  if (formatPointer(fromTokens) === formatPointer(pathTokens)) return document;
  const isProperPrefix = fromTokens.length < pathTokens.length && fromTokens.every((token, i) => token === pathTokens[i]);
  if (isProperPrefix) throw new Error('cannot move a value into its own child');
  const value = cloneJSON(resolve(document, from));
  doRemove(document, from);
  return doAdd(document, path, value);
}

/** Apply `copy`, mutating `document` in place and returning it. */
function doCopy(document, path, from) {
  const value = cloneJSON(resolve(document, from));
  return doAdd(document, path, value);
}

/** Apply `test`, throwing when the comparison fails, and otherwise returning `document` unchanged. */
function doTest(document, path, rawValue) {
