    .slice(1)
    .split('/')
    .map((raw) => decodeToken(raw, pointer));
}

/** Decode one raw reference token, resolving `~1` and `~0` in a single left-to-right pass. */
function decodeToken(raw, pointer) {
  let out = '';
  for (let i = 0; i < raw.length; i += 1) {
    const character = raw[i];
    if (character !== '~') {
      out += character;
      continue;
    }
