    if (index > parent.length) throw new PointerError(`index out of range: ${token} at ${at}`, at);
    parent.splice(index, 0, value);
    return root;
  }
  if (parent !== null && typeof parent === 'object') {
    setOwn(parent, token, value);
    return root;
  }
  throw new PointerError(`cannot index into ${typeName(parent)} at ${at}`, at);
}

/** Remove the value at `tokens` and return it. */
function removeAt(root, tokens) {
  const parent = resolveTokens(root, tokens.slice(0, -1));
  const token = tokens[tokens.length - 1];
  const at = formatPointer(tokens);
  if (Array.isArray(parent)) {
    if (!isArrayIndex(token)) throw new PointerError(`invalid array index: ${token} at ${at}`, at);
