  if (typeof state !== 'string' || !Object.prototype.hasOwnProperty.call(TABLE, state)) {
    throw new TypeError(`unknown state: ${state}`);
  }
  return [...TABLE[state]];
}

/**
 * Report whether a state accepts no further command.
 *
 * @param {string} state State to look up.
 * @returns {boolean} True for a terminal state.
 */
export function isTerminal(state) {
  return allowedTypes(state).length === 0;
}
