{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATOR_CHARS = '+#./;?&';
const RESERVED_OPERATOR_CHARS = '=,!@|';
const NAME_RE = /^([A-Za-z0-9_]|%[0-9A-Fa-f]{2})(\.([A-Za-z0-9_]|%[0-9A-Fa-f]{2}))*$/;
const MOD_RE = /^[1-9][0-9]{0,3}$/;

function parseVarSpec(spec, start) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);

  let explode = false;
  let maxLength = null;
  let namePart;

  if (spec.endsWith('*')) {
    explode = true;
    namePart = spec.slice(0, -1);
  } else {
    const colonIdx = spec.indexOf(':');
    if (colonIdx !== -1) {
      namePart = spec.slice(0, colonIdx);
      const modPart = spec.slice(colonIdx + 1);
      if (!MOD_RE.test(modPart)) {
        throw new UriTemplateError(`invalid prefix modifier ':${modPart}' at ${start}`, start);
      }
      maxLength = Number(modPart);
    } else {
      namePart = spec;
    }
  }

  if (!NAME_RE.test(namePart)) {
    throw new UriTemplateError(`invalid variable name '${namePart}' at ${start}`, start);
  }

  return { name: namePart, explode, maxLength };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let literalBuf = '';
  let i = 0;

  while (i < template.length) {
    const c = template[i];

    if (c === '{') {
      if (literalBuf) {
        parts.push({ type: 'literal', value: literalBuf });
        literalBuf = '';
      }
      const start = i;
      const j = template.indexOf('}', i + 1);
      if (j === -1) throw new UriTemplateError(`unterminated expression at ${start}`, start);
      const content = template.slice(i + 1, j);
      if (content === '') throw new UriTemplateError(`empty expression at ${start}`, start);

      let operator = '';
      let rest = content;
      const first = content[0];
      if (OPERATOR_CHARS.includes(first)) {
        operator = first;
        rest = content.slice(1);
      } else if (RESERVED_OPERATOR_CHARS.includes(first)) {
        throw new UriTemplateError(`reserved operator '${first}' at ${start}`, start);
      }

      const specs = rest.split(',');
      const variables = specs.map((spec) => parseVarSpec(spec, start));
      parts.push({ type: 'expression', operator, variables });

      i = j + 1;
      continue;
    }

    if (c === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    }

    literalBuf += c;
    i += 1;
  }

  if (literalBuf) parts.push({ type: 'literal', value: literalBuf });

  return parts;
}
"}

