/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const WHITESPACE = /\s/;
const NAME_START = /[A-Za-z_]/;
const NAME_PART = /[A-Za-z0-9_]/;
const NUMBER = /(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/y;
const PUNCTUATION = { '(': 'lparen', ')': 'rparen', ',': 'comma' };
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);

/**
 * Split an expression into tokens, keeping the raw source text of each one.
 *
 * @param {string} input expression source
 * @returns {{ tokens: object[], texts: string[] }} tokens and their source slices
 */
export function tokenizeWithText(input) {
  const source = String(input);
  const tokens = [];
  const texts = [];
  let position = 0;

  while (position < source.length) {
    const character = source[position];

    if (WHITESPACE.test(character)) {
      position += 1;
      continue;
    }

    if (character >= '0' && character <= '9') {
      position = readNumber(source, position, tokens, texts);
      continue;
    }

    if (character === '.' && /\d/.test(source[position + 1] ?? '')) {
      position = readNumber(source, position, tokens, texts);
      continue;
    }

    if (NAME_START.test(character)) {
      const start = position;
      position += 1;
      while (position < source.length && NAME_PART.test(source[position])) position += 1;
      const text = source.slice(start, position);
      tokens.push({ type: 'name', value: text, index: start });
      texts.push(text);
      continue;
    }

    if (OPERATORS.has(character)) {
      tokens.push({ type: 'operator', value: character, index: position });
      texts.push(character);
      position += 1;
      continue;
    }

    const punctuation = PUNCTUATION[character];
    if (punctuation !== undefined) {
      tokens.push({ type: punctuation, value: character, index: position });
      texts.push(character);
      position += 1;
      continue;
    }

    const codePoint = String.fromCodePoint(source.codePointAt(position));
    throw new ExprError(`unexpected character '${codePoint}' at ${position}`, position);
  }

  return { tokens, texts };
}

/** Read one numeric literal, rejecting anything that only starts like a number. */
function readNumber(source, start, tokens, texts) {
  NUMBER.lastIndex = start;
  const match = NUMBER.exec(source);
  if (match === null || match.index !== start) throw new ExprError(`malformed number at ${start}`, start);
  const end = start + match[0].length;
  const next = source[end];
  if (next !== undefined && (next === '.' || NAME_PART.test(next))) {
    throw new ExprError(`malformed number at ${start}`, start);
  }
  tokens.push({ type: 'number', value: Number(match[0]), index: start });
  texts.push(match[0]);
  return end;
}

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  return tokenizeWithText(input).tokens;
}
"}

{"file_path":"src/parse.js","content":"/** Precedence-climbing parser producing the expression tree. */

import { ExprError, tokenizeWithText } from './tokenize.js';

const ADDITIVE = new Set(['+', '-']);
const MULTIPLICATIVE = new Set(['*', '/', '%']);

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const source = String(input);
  const { tokens, texts } = tokenizeWithText(source);
  const state = { tokens, texts, position: 0, length: source.length };
  const node = parseAdditive(state);
  if (state.position < tokens.length) throw unexpected(state);
  return node;
}

function peek(state) {
  return state.tokens[state.position];
}

function unexpected(state) {
  const token = peek(state);
  if (token === undefined) return new ExprError(`unexpected end of input at ${state.length}`, state.length);
  const text = state.texts[state.position];
  return new ExprError(`unexpected token '${text}' at ${token.index}`, token.index);
}

function isOperator(token, set) {
  return token !== undefined && token.type === 'operator' && set.has(token.value);
}

function parseAdditive(state) {
  let left = parseMultiplicative(state);
  while (isOperator(peek(state), ADDITIVE)) {
    const token = state.tokens[state.position];
    state.position += 1;
    const right = parseMultiplicative(state);
    left = { type: 'binary', op: token.value, left, right, index: token.index };
  }
  return left;
}

function parseMultiplicative(state) {
  let left = parseUnary(state);
  while (isOperator(peek(state), MULTIPLICATIVE)) {
    const token = state.tokens[state.position];
    state.position += 1;
    const right = parseUnary(state);
    left = { type: 'binary', op: token.value, left, right, index: token.index };
  }
  return left;
}

function parseUnary(state) {
  const token = peek(state);
  if (isOperator(token, ADDITIVE)) {
    state.position += 1;
    const operand = parseUnary(state);
    return { type: 'unary', op: token.value, operand, index: token.index };
  }
  return parsePower(state);
}

function parsePower(state) {
  const base = parsePrimary(state);
  const token = peek(state);
  if (token !== undefined && token.type === 'operator' && token.value === '^') {
    state.position += 1;
    const right = parseUnary(state);
    return { type: 'binary', op: '^', left: base, right, index: token.index };
  }
  return base;
}

function parsePrimary(state) {
  const token = peek(state);
  if (token === undefined) throw unexpected(state);

  if (token.type === 'number') {
    state.position += 1;
    return { type: 'number', value: token.value, index: token.index };
  }

  if (token.type === 'name') {
    state.position += 1;
    const next = peek(state);
    if (next !== undefined && next.type === 'lparen') {
      state.position += 1;
      const args = [];
      if (peek(state) !== undefined && peek(state).type === 'rparen') {
        state.position += 1;
      } else {
        for (;;) {
          args.push(parseAdditive(state));
          const separator = peek(state);
          if (separator === undefined) {
            throw new ExprError(`missing closing parenthesis at ${state.length}`, state.length);
          }
          if (separator.type === 'comma') {
            state.position += 1;
            continue;
          }
          if (separator.type === 'rparen') {
            state.position += 1;
            break;
          }
          throw unexpected(state);
        }
      }
      return { type: 'call', name: token.value, args, index: token.index };
    }
    return { type: 'variable', name: token.value, index: token.index };
  }

  if (token.type === 'lparen') {
    state.position += 1;
    const inner = parseAdditive(state);
    const closing = peek(state);
    if (closing === undefined || closing.type !== 'rparen') {
      const index = closing === undefined ? state.length : closing.index;
      throw new ExprError(`missing closing parenthesis at ${index}`, index);
    }
    state.position += 1;
    return inner;
  }

  throw unexpected(state);
}
"}

