 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

/** Fixed function table: implementation plus arity, where `max` means unbounded. */
const FUNCTIONS = {
  abs: { min: 1, max: 1, apply: (a) => Math.abs(a) },
  sqrt: { min: 1, max: 1, apply: (a) => Math.sqrt(a) },
  floor: { min: 1, max: 1, apply: (a) => Math.floor(a) },
  ceil: { min: 1, max: 1, apply: (a) => Math.ceil(a) },
  round: { min: 1, max: 1, apply: (a) => Math.round(a) },
  sign: { min: 1, max: 1, apply: (a) => Math.sign(a) },
  pow: { min: 2, max: 2, apply: (a, b) => a ** b },
  atan2: { min: 2, max: 2, apply: (a, b) => Math.atan2(a, b) },
  min: { min: 1, max: Infinity, apply: (...values) => Math.min(...values) },
  max: { min: 1, max: Infinity, apply: (...values) => Math.max(...values) },
};

const plural = (count) => (count === 1 ? 'argument' : 'arguments');

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  return walk(parse(input), env ?? {});
}

/** Recursively evaluate one node in JavaScript double arithmetic. */
function walk(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'variable':
      return lookup(node, env);
    case 'unary': {
      const operand = walk(node.operand, env);
      const value = node.op === '-' ? -operand : operand;
      return checkFinite(value, node.index);
    }
    case 'binary':
      return applyBinary(node, env);
    case 'call':
      return applyCall(node, env);
    default:
      throw new ExprError(`unexpected token at ${node.index}`, node.index);
  }
}

/** Resolve a name against the environment, then the built-in constants. */
function lookup(node, env) {
  const isBinding =
    env !== null && typeof env === 'object' && Object.prototype.hasOwnProperty.call(env, node.name);
  if (isBinding) {
