 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { arity: 1, fn: (a) => Math.abs(a) },
  sqrt: { arity: 1, fn: (a) => Math.sqrt(a) },
  floor: { arity: 1, fn: (a) => Math.floor(a) },
  ceil: { arity: 1, fn: (a) => Math.ceil(a) },
  round: { arity: 1, fn: (a) => Math.round(a) },
  sign: { arity: 1, fn: (a) => Math.sign(a) },
  pow: { arity: 2, fn: (a, b) => Math.pow(a, b) },
  atan2: { arity: 2, fn: (a, b) => Math.atan2(a, b) },
  min: { arity: -1, fn: (...args) => Math.min(...args) },
  max: { arity: -1, fn: (...args) => Math.max(...args) },
};

function resolveVariable(name, env, index) {
  if (Object.prototype.hasOwnProperty.call(env, name)) {
    const value = env[name];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new ExprError(`variable ${name} is not a finite number at ${index}`, index);
    }
    return value;
  }
  if (Object.prototype.hasOwnProperty.call(CONSTANTS, name)) {
    return CONSTANTS[name];
  }
  throw new ExprError(`unknown variable: ${name} at ${index}`, index);
}

function evalNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'variable':
      return resolveVariable(node.name, env, node.index);
    case 'unary': {
      const value = evalNode(node.operand, env);
      return node.op === '-' ? -value : value;
    }
    case 'binary': {
      const left = evalNode(node.left, env);
      const right = evalNode(node.right, env);
      let result;
      switch (node.op) {
        case '+':
          result = left + right;
          break;
        case '-':
          result = left - right;
          break;
        case '*':
          result = left * right;
          break;
        case '/':
          if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
          result = left / right;
          break;
        case '%':
          if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
          result = left % right;
          break;
        case '^':
          result = Math.pow(left, right);
          break;
        default:
          throw new ExprError(`unexpected operator ${node.op} at ${node.index}`, node.index);
      }
      if (!Number.isFinite(result)) {
        throw new ExprError(`non-finite result at ${node.index}`, node.index);
      }
      return result;
    }
    case 'call': {
      const spec = FUNCTIONS[node.name];
      if (spec === undefined) {
        throw new ExprError(`unknown function: ${node.name} at ${node.index}`, node.index);
      }
      const args = node.args.map((arg) => evalNode(arg, env));
      if (spec.arity === -1) {
        if (args.length < 1) {
          throw new ExprError(
            `function ${node.name} expects at least 1 argument, got ${args.length} at ${node.index}`,
            node.index,
          );
        }
      } else if (args.length !== spec.arity) {
        const word = spec.arity === 1 ? 'argument' : 'arguments';
        throw new ExprError(
          `function ${node.name} expects ${spec.arity} ${word}, got ${args.length} at ${node.index}`,
          node.index,
        );
      }
      const result = spec.fn(...args);
      if (!Number.isFinite(result)) {
        throw new ExprError(`non-finite result at ${node.index}`, node.index);
      }
      return result;
    }
    default:
      throw new ExprError(`unexpected node type ${node.type} at ${node.index}`, node.index);
  }
}

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  const tree = parse(input);
  return evalNode(tree, env);
}
"}

