/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATORS = '+#./;?&';
const RESERVED_OPERATORS = '=,!@|';
const NAME_RE = /^(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+(?:\.(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+)*$/;
const PREFIX_DIGITS_RE = /^[1-9][0-9]{0,3}$/;

function parseVarSpec(spec, bracePos) {
  let explode = false;
  let maxLength = null;
  let namePart;

  if (spec.endsWith('*')) {
    explode = true;
    namePart = spec.slice(0, -1);
  } else if (spec.includes(':')) {
    const idx = spec.indexOf(':');
    namePart = spec.slice(0, idx);
    const modText = spec.slice(idx + 1);
    if (PREFIX_DIGITS_RE.test(modText)) {
      maxLength = Number(modText);
    } else {
      throw new UriTemplateError(`invalid prefix modifier ':${modText}' at ${bracePos}`, bracePos);
    }
  } else {
    namePart = spec;
  }

  if (!NAME_RE.test(namePart)) {
    throw new UriTemplateError(`invalid variable name '${namePart}' at ${bracePos}`, bracePos);
  }

  return { name: namePart, explode, maxLength };
}

function parseExpressionContent(content, bracePos) {
  if (content === '') {
    throw new UriTemplateError(`empty expression at ${bracePos}`, bracePos);
  }

  const firstChar = content[0];
  let operator = '';
  let rest = content;

  if (OPERATORS.includes(firstChar)) {
    operator = firstChar;
    rest = content.slice(1);
  } else if (RESERVED_OPERATORS.includes(firstChar)) {
    throw new UriTemplateError(`reserved operator '${firstChar}' at ${bracePos}`, bracePos);
  }

  if (rest === '') {
    throw new UriTemplateError(`empty variable specification at ${bracePos}`, bracePos);
  }

  const specs = rest.split(',');
  const variables = [];
  for (const spec of specs) {
    if (spec === '') {
      throw new UriTemplateError(`empty variable specification at ${bracePos}`, bracePos);
    }
    variables.push(parseVarSpec(spec, bracePos));
  }

  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let literalBuf = '';
  let i = 0;
  const len = template.length;

  while (i < len) {
    const ch = template[i];
    if (ch === '{') {
      if (literalBuf !== '') {
        parts.push({ type: 'literal', value: literalBuf });
        literalBuf = '';
      }
      const closeIdx = template.indexOf('}', i + 1);
      if (closeIdx === -1) {
        throw new UriTemplateError(`unterminated expression at ${i}`, i);
      }
      const content = template.slice(i + 1, closeIdx);
      parts.push(parseExpressionContent(content, i));
      i = closeIdx + 1;
      continue;
    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literalBuf += ch;
      i += 1;
    }
  }

  if (literalBuf !== '') {
    parts.push({ type: 'literal', value: literalBuf });
  }

  return parts;
}
"}

