import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /[A-Za-z0-9\-._~]/;
const RESERVED_RE = /[:/?#[\]@!$&'()*+,;=]/;
const HEX_RE = /^[0-9A-Fa-f]$/;

function utf8PercentEncode(codePoint) {
  const bytes = Buffer.from(codePoint, 'utf8');
  let out = '';
  for (const byte of bytes) {
    out += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
  }
  return out;
}

function encodeString(str, { preserveReserved, preservePercentTriplets }) {
  const codePoints = Array.from(str);
  let out = '';
  let i = 0;
  while (i < codePoints.length) {
    const c = codePoints[i];
    if (
      preservePercentTriplets &&
      c === '%' &&
      i + 2 < codePoints.length &&
      HEX_RE.test(codePoints[i + 1]) &&
      HEX_RE.test(codePoints[i + 2])
    ) {
      out += '%' + codePoints[i + 1] + codePoints[i + 2];
      i += 3;
      continue;
    }
    if (UNRESERVED_RE.test(c) || (preserveReserved && RESERVED_RE.test(c))) {
      out += c;
      i += 1;
      continue;
    }
    out += utf8PercentEncode(c);
    i += 1;
  }
  return out;
}

/** Encode literal template text: keep unreserved/reserved chars and existing percent-triplets. */
function encodeLiteral(str) {
  return encodeString(str, { preserveReserved: true, preservePercentTriplets: true });
}

/** Encode a value under `+`/`#`: same rules as literal text. */
function encodeReservedValue(str) {
  return encodeString(str, { preserveReserved: true, preservePercentTriplets: true });
}

/** Encode a value under any other operator: only unreserved characters survive. */
function encodeUnreservedValue(str) {
  return encodeString(str, { preserveReserved: false, preservePercentTriplets: false });
}

const OPERATOR_INFO = {
  '': { prefix: '', sep: ',', named: false, emptyText: '', encode: encodeUnreservedValue },
  '+': { prefix: '', sep: ',', named: false, emptyText: '', encode: encodeReservedValue },
  '#': { prefix: '#', sep: ',', named: false, emptyText: '', encode: encodeReservedValue },
  '.': { prefix: '.', sep: '.', named: false, emptyText: '', encode: encodeUnreservedValue },
  '/': { prefix: '/', sep: '/', named: false, emptyText: '', encode: encodeUnreservedValue },
  ';': { prefix: ';', sep: ';', named: true, emptyText: '', encode: encodeUnreservedValue },
  '?': { prefix: '?', sep: '&', named: true, emptyText: '=', encode: encodeUnreservedValue },
  '&': { prefix: '&', sep: '&', named: true, emptyText: '=', encode: encodeUnreservedValue },
};

function scalarToString(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
    }
    return String(value);
  }
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

function encodeScalar(value, name, encodeFn, maxLength) {
  let str = scalarToString(value, name);
  if (maxLength !== null && maxLength !== undefined) {
    str = Array.from(str).slice(0, maxLength).join('');
  }
  return encodeFn(str);
}

function namedPiece(name, encodedValue, opInfo) {
  if (encodedValue === '') return `${name}${opInfo.emptyText}`;
  return `${name}=${encodedValue}`;
}

function getPieces(varSpec, value, opInfo) {
  const { name, explode, maxLength } = varSpec;

  if (value === null || value === undefined) return [];

  if (Array.isArray(value)) {
    const items = value.filter((item) => item !== null && item !== undefined);
    if (items.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    const encodedItems = items.map((item) => encodeScalar(item, name, opInfo.encode, null));
    if (explode) {
      return encodedItems.map((enc) => (opInfo.named ? namedPiece(name, enc, opInfo) : enc));
    }
    const joined = encodedItems.join(',');
    return [opInfo.named ? namedPiece(name, joined, opInfo) : joined];
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).filter(([, v]) => v !== null && v !== undefined);
    if (entries.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    if (explode) {
      return entries.map(([k, v]) => {
        const encKey = encodeScalar(k, name, opInfo.encode, null);
        const encVal = encodeScalar(v, name, opInfo.encode, null);
        if (opInfo.named && encVal === '') return `${encKey}${opInfo.emptyText}`;
        return `${encKey}=${encVal}`;
      });
    }
    const flat = [];
    for (const [k, v] of entries) {
      flat.push(opInfo.encode(k));
      flat.push(encodeScalar(v, name, opInfo.encode, null));
    }
    const joined = flat.join(',');
    return [opInfo.named ? namedPiece(name, joined, opInfo) : joined];
  }

  // scalar
  const enc = encodeScalar(value, name, opInfo.encode, maxLength);
  if (opInfo.named) {
    return [namedPiece(name, enc, opInfo)];
  }
  return [enc];
}

function expandExpression(part, variables) {
  const opInfo = OPERATOR_INFO[part.operator];
  let allPieces = [];
  for (const varSpec of part.variables) {
    if (!Object.prototype.hasOwnProperty.call(variables, varSpec.name)) continue;
    const value = variables[varSpec.name];
    const pieces = getPieces(varSpec, value, opInfo);
    allPieces = allPieces.concat(pieces);
  }
  if (allPieces.length === 0) return '';
  return opInfo.prefix + allPieces.join(opInfo.sep);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  const parts = parse(template);
  if (variables === null || typeof variables !== 'object') {
    throw new UriTemplateError('variables must be an object');
  }
  let result = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeLiteral(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }
  return result;
}
"}

