{"file_path":"src/dsu.js","content":"/**
 * Disjoint sets over the elements `0 .. count - 1`, joined by size and undone
 * in reverse order.
 */

/**
 * Checks that a value is a usable element count.
 * @param {unknown} count Candidate count.
 * @returns {number} The validated count.
 */
export function validateCount(count) {
  if (typeof count !== 'number' || !Number.isSafeInteger(count) || count < 0) {
    throw new TypeError('count must be a non-negative integer');
  }
  return count;
}

export class DisjointSets {
  #parent;
  #size;
  #components;
  #history;

  /**
   * @param {number} count How many elements the structure holds.
   */
  constructor(count) {
    validateCount(count);
    this.#parent = Array.from({ length: count }, (_, index) => index);
    this.#size = new Array(count).fill(1);
    this.#components = count;
    this.#history = [];
  }

  /** @returns {number} How many elements the structure holds. */
  get count() {
    return this.#parent.length;
  }

  /** @returns {number} How many disjoint sets exist right now. */
  get components() {
    return this.#components;
  }

  /**
   * Validates an element index.
   * @param {unknown} element Candidate element.
   * @returns {number} The validated element.
   */
  #check(element) {
    if (
      typeof element !== 'number' ||
      !Number.isSafeInteger(element) ||
      element < 0 ||
      element >= this.#parent.length
    ) {
      throw new RangeError(`element out of range: ${element}`);
    }
    return element;
  }

  /**
   * Finds the representative of an element's set.
   * @param {number} element Element to look up.
   * @returns {number} Root element of the set.
   */
  find(element) {
    let node = this.#check(element);
    while (this.#parent[node] !== node) node = this.#parent[node];
    return node;
  }

  /**
   * Reports whether two elements share a set.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} True when both share a representative.
   */
  connected(a, b) {
    return this.find(a) === this.find(b);
  }

  /**
   * Reports how many elements share an element's set.
   * @param {number} element Element to measure.
   * @returns {number} Size of the set.
   */
  sizeOf(element) {
    return this.#size[this.find(element)];
  }

  /**
   * Joins two sets, attaching the smaller under the larger and, on a tie, the
   * larger root index under the smaller.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} False when both elements already shared a set.
   */
  union(a, b) {
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return false;
    let root;
    if (this.#size[rootB] > this.#size[rootA]) root = rootB;
    else if (this.#size[rootA] > this.#size[rootB]) root = rootA;
    else root = Math.min(rootA, rootB);
    const attached = root === rootA ? rootB : rootA;
    this.#parent[attached] = root;
    this.#size[root] += this.#size[attached];
    this.#components -= 1;
    this.#history.push([root, attached]);
    return true;
  }

  /**
   * Marks the current state so it can be restored later.
   * @returns {number} Token naming this state.
   */
  checkpoint() {
    return this.#history.length;
  }

  /**
   * Undoes the most recent union.
   * @returns {boolean} False when no union was left to undo.
   */
  undo() {
    const entry = this.#history.pop();
    if (entry === undefined) return false;
    const [root, attached] = entry;
    this.#size[root] -= this.#size[attached];
    this.#parent[attached] = attached;
    this.#components += 1;
    return true;
  }

  /**
   * Undoes unions until the state matches a checkpoint.
   * @param {number} token Token from `checkpoint`.
   * @returns {number} How many unions were undone.
   */
  rollback(token) {
    if (
      typeof token !== 'number' ||
      !Number.isSafeInteger(token) ||
      token < 0 ||
      token > this.#history.length
    ) {
      throw new RangeError(`unknown checkpoint: ${token}`);
    }
    let undone = 0;
    while (this.#history.length > token) {
      this.undo();
      undone += 1;
    }
    return undone;
  }

  /**
   * Lists the sets, each sorted ascending, ordered by their smallest member.
   * @returns {number[][]} Current partition.
   */
  groups() {
    /** @type {Map<number, number[]>} */
    const byRoot = new Map();
    for (let element = 0; element < this.#parent.length; element += 1) {
      const root = this.find(element);
      if (!byRoot.has(root)) byRoot.set(root, []);
      byRoot.get(root).push(element);
    }
    return [...byRoot.values()].sort((a, b) => a[0] - b[0]);
  }
}
"}

{"file_path":"src/kruskal.js","content":"/**
 * Spanning-forest and what-if queries built on the rollback-capable
 * disjoint-set structure.
 *
 * An edge is `[u, v, weight]` with element indices and a finite weight.
 */

import { DisjointSets, validateCount } from './dsu.js';

/**
 * Validates a list of edges against an element count.
 * @param {unknown} edges Candidate edge list.
 * @param {number} count Element count.
 * @returns {Array<[number, number, number]>} The validated edges.
 */
function validateEdges(edges, count) {
  if (!Array.isArray(edges)) throw new TypeError('edges must be an array');
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) {
      throw new TypeError('edge must be [u, v, weight]');
    }
    const [u, v, weight] = edge;
    if (typeof weight !== 'number' || !Number.isFinite(weight)) {
      throw new TypeError('weight must be a finite number');
    }
    for (const element of [u, v]) {
      if (
        typeof element !== 'number' ||
        !Number.isSafeInteger(element) ||
        element < 0 ||
        element >= count
      ) {
        throw new RangeError(`element out of range: ${element}`);
      }
    }
  }
  return edges;
}

/**
 * Builds a minimum spanning forest with Kruskal's algorithm, taking edges by
 * weight and breaking ties by the first endpoint and then the second.
 * @param {number} count Element count.
 * @param {unknown} edges Available edges.
 * @returns {{edges: Array<[number, number, number]>, weight: number, components: number}} Chosen edges, their total weight, and the remaining component count.
 */
export function minimumSpanningForest(count, edges) {
  validateCount(count);
  const list = validateEdges(edges, count).slice();
  list.sort((a, b) => a[2] - b[2] || a[0] - b[0] || a[1] - b[1]);
  const sets = new DisjointSets(count);
  /** @type {Array<[number, number, number]>} */
  const chosen = [];
  let weight = 0;
  for (const edge of list) {
    if (sets.union(edge[0], edge[1])) {
      chosen.push(edge);
      weight += edge[2];
    }
  }
  return { edges: chosen, weight, components: sets.components };
}

/**
 * Measures how many components remain after each alternative edge set is
 * added on top of a shared base, evaluating each alternative independently by
 * rolling back to the state the base left behind.
 * @param {number} count Element count.
 * @param {unknown} baseEdges Edges applied once, before any alternative.
 * @param {unknown} alternatives Array of edge lists to try one at a time.
 * @returns {{base: number, alternatives: number[]}} Component count for the base and for each alternative.
 */
export function componentsWithAlternatives(count, baseEdges, alternatives) {
  validateCount(count);
  const base = validateEdges(baseEdges, count);
  if (!Array.isArray(alternatives)) throw new TypeError('alternatives must be an array');
  const lists = alternatives.map((edges) => validateEdges(edges, count));

  const sets = new DisjointSets(count);
  for (const [u, v] of base) sets.union(u, v);
  const token = sets.checkpoint();
  const results = [];
  for (const list of lists) {
    for (const [u, v] of list) sets.union(u, v);
    results.push(sets.components);
    sets.rollback(token);
  }
  return { base: sets.components, alternatives: results };
}
"}

