test('lexical failures report the offending position', () => {
  const cases = [
    ['1 + $', /unexpected character '\$' at 4/, 4],
    ['1 + \u{1f600}', /unexpected character '\u{1f600}' at 4/u, 4],
    ['1.2.3', /malformed number at 0/, 0],
    ['1e', /malformed number at 0/, 0],
    ['1e+', /malformed number at 0/, 0],
