import { ExprError, tokenize } from './tokenize.js';

function tokenText(token) {
  if (token.type === 'number') return String(token.value);
  return String(token.value);
}

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  const end = input.length;
  let pos = 0;

  const peek = () => tokens[pos];
  const advance = () => tokens[pos++];

  function expectExpression() {
    const token = peek();
    if (token === undefined) throw new ExprError(`unexpected end of input at ${end}`, end);
    return token;
  }

  function parsePrimary() {
    const token = expectExpression();
    if (token.type === 'number') {
      advance();
      return { type: 'number', value: token.value, index: token.index };
    }
    if (token.type === 'name') {
      advance();
      const next = peek();
      if (next !== undefined && next.type === 'lparen') {
        const args = parseCallArgs();
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }
    if (token.type === 'lparen') {
      advance();
      const node = parseExpr();
      const closer = peek();
      if (closer !== undefined && closer.type === 'rparen') {
        advance();
        return node;
      }
      const idx = closer !== undefined ? closer.index : end;
      throw new ExprError(`missing closing parenthesis at ${idx}`, idx);
    }
    throw new ExprError(`unexpected token '${tokenText(token)}' at ${token.index}`, token.index);
  }

  function parseCallArgs() {
    advance(); // consume lparen
    const args = [];
    const first = peek();
    if (first !== undefined && first.type === 'rparen') {
      advance();
      return args;
    }
    for (;;) {
      args.push(parseExpr());
      const token = peek();
      if (token === undefined) throw new ExprError(`unexpected end of input at ${end}`, end);
      if (token.type === 'comma') {
        advance();
        continue;
      }
      if (token.type === 'rparen') {
        advance();
        break;
      }
      throw new ExprError(`unexpected token '${tokenText(token)}' at ${token.index}`, token.index);
    }
    return args;
  }

  function parseUnary() {
    const token = peek();
    if (token !== undefined && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
