import { copyJson, jsonEqual, setMember } from './json.js';
import { PointerError, formatPointer, isArrayIndex, parsePointer, resolveTokens, typeName } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

/** The operations a patch may contain, with the members each one needs. */
const OPERATIONS = {
  add: { value: true },
  remove: {},
  replace: { value: true },
  move: { from: true },
  copy: { from: true },
  test: { value: true },
};

/**
 * Check one operation's shape and decode its pointers.
 *
 * @param {unknown} operation a member of the patch
 * @returns {{ op: string, path: string[], from: string[] | null, value: unknown }} the checked operation
 */
function checkOperation(operation) {
  if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) {
    throw new PatchError('operation must be an object');
  }
  const op = operation.op;
  if (typeof op !== 'string' || !hasOwn(OPERATIONS, op)) {
    throw new PatchError(`unknown operation: ${op}`);
  }
  const needs = OPERATIONS[op];
  if (!hasOwn(operation, 'path')) throw new PatchError(`${op} requires a path`);
  if (needs.value && !hasOwn(operation, 'value')) throw new PatchError(`${op} requires a value`);
  if (needs.from && !hasOwn(operation, 'from')) throw new PatchError(`${op} requires a from`);
  return {
    op,
    path: parsePointer(operation.path),
    from: needs.from ? parsePointer(operation.from) : null,
    value: operation.value,
  };
}

/**
 * Find the container a pointer's last token addresses.
 *
 * @param {unknown} root the document being patched
 * @param {string[]} tokens the target's decoded tokens, at least one
 * @returns {{ parent: unknown, token: string, at: string }} the container, the last token and the target pointer
 */
function locate(root, tokens) {
  const at = formatPointer(tokens);
  const parent = resolveTokens(root, tokens.slice(0, -1));
  return { parent, token: tokens[tokens.length - 1], at };
}

/**
 * Read the array position a token names, for an operation that needs the element to exist.
 *
 * @param {unknown[]} array the array being addressed
 * @param {string} token the reference token
 * @param {string} at the pointer to the target
 * @returns {number} the position
 */
function existingIndex(array, token, at) {
  if (!isArrayIndex(token)) throw new PointerError(`invalid array index: ${token} at ${at}`, at);
  const index = Number(token);
  if (index >= array.length) throw new PointerError(`index out of range: ${token} at ${at}`, at);
  return index;
}

/**
 * Store a value at a target, inserting into arrays and creating object members.
 *
 * @param {unknown} parent the container to write to
 * @param {string} token the reference token naming the target
 * @param {string} at the pointer to the target
 * @param {unknown} value the value to store, already copied
 * @returns {void}
 */
function addAt(parent, token, at, value) {
  if (Array.isArray(parent)) {
    if (token === '-') {
      parent.push(value);
      return;
    }
    if (!isArrayIndex(token)) throw new PointerError(`invalid array index: ${token} at ${at}`, at);
