function removeAt(parent, token, at) {
  if (Array.isArray(parent)) return parent.splice(existingIndex(parent, token, at), 1)[0];
  if (parent !== null && typeof parent === 'object') {
    if (!hasOwn(parent, token)) throw new PointerError(`missing property: ${token} at ${at}`, at);
    const removed = parent[token];
    delete parent[token];
    return removed;
  }
  throw new PointerError(`cannot index into ${typeName(parent)} at ${at}`, at);
