 * Whether one token sequence is a proper prefix of another.
 *
 * @param {string[]} prefix the shorter candidate
 * @param {string[]} tokens the longer candidate
 * @returns {boolean} true when prefix names an ancestor of tokens
 */
function isProperPrefix(prefix, tokens) {
  return prefix.length < tokens.length && prefix.every((token, index) => token === tokens[index]);
