/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const NUMBER = /(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/y;
const NAME = /[A-Za-z_][A-Za-z0-9_]*/y;
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);
const PUNCTUATION = { '(': 'lparen', ')': 'rparen', ',': 'comma' };

const isDigit = (ch) => ch >= '0' && ch <= '9';
const isNumberTail = (ch) =>
  ch !== undefined && (isDigit(ch) || ch === '.' || ch === '_' || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'));

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const source = String(input);
  const tokens = [];
  let position = 0;

  while (position < source.length) {
    const ch = source[position];

    if (/\s/.test(ch)) {
      position += 1;
      continue;
    }

    if (isDigit(ch) || ch === '.') {
      NUMBER.lastIndex = position;
      const match = NUMBER.exec(source);
      if (match === null || isNumberTail(source[position + match[0].length])) {
        throw new ExprError(`malformed number at ${position}`, position);
      }
      tokens.push({ type: 'number', value: Number(match[0]), index: position });
      position += match[0].length;
      continue;
    }

    if (/[A-Za-z_]/.test(ch)) {
      NAME.lastIndex = position;
      const match = NAME.exec(source);
      tokens.push({ type: 'name', value: match[0], index: position });
      position += match[0].length;
      continue;
    }

    if (OPERATORS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: position });
      position += 1;
      continue;
    }

    if (Object.hasOwn(PUNCTUATION, ch)) {
      tokens.push({ type: PUNCTUATION[ch], value: ch, index: position });
      position += 1;
