import { ExprError } from './tokenize.js';
import { parse } from './parse.js';

const CONSTANTS = { pi: Math.PI, e: Math.E };

/** Ties round toward positive infinity, matching Math.round. */
const FUNCTIONS = {
  abs: { arity: 1, apply: (a) => Math.abs(a) },
  sqrt: { arity: 1, apply: (a) => Math.sqrt(a) },
  floor: { arity: 1, apply: (a) => Math.floor(a) },
  ceil: { arity: 1, apply: (a) => Math.ceil(a) },
  round: { arity: 1, apply: (a) => Math.round(a) },
  sign: { arity: 1, apply: (a) => Math.sign(a) },
  pow: { arity: 2, apply: (a, b) => a ** b },
  atan2: { arity: 2, apply: (a, b) => Math.atan2(a, b) },
  min: { arity: null, apply: (...args) => Math.min(...args) },
  max: { arity: null, apply: (...args) => Math.max(...args) },
};

const plural = (count) => (count === 1 ? 'argument' : 'arguments');

function finite(value, index) {
  if (!Number.isFinite(value)) throw new ExprError(`non-finite result at ${index}`, index);
  return value;
}

function lookup(name, env, index) {
  const bound = env !== null && typeof env === 'object' && Object.hasOwn(env, name);
  if (!bound) {
    if (Object.hasOwn(CONSTANTS, name)) return CONSTANTS[name];
    throw new ExprError(`unknown variable: ${name} at ${index}`, index);
  }
