{"file_path":"src/patch.js","content":"/** JSON Patch application with all-or-nothing semantics. */

import { PointerError, formatPointer, parsePointer, resolve, stepInto, typeName } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

/**
 * Verify a value is JSON-representable and return a deep copy of it.
 *
 * @param {unknown} value the value to check and copy
 * @param {string} label what to call it in the error, e.g. 'document' or 'value'
 * @returns {unknown} an independent deep copy
 */
function cloneJson(value, label) {
  if (value === null) return null;
  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') return value;
  if (Array.isArray(value)) return value.map((item) => cloneJson(item, label));
  if (type === 'object') {
    if (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) {
      throw new Error(`${label} is not JSON data`);
    }
    const result = {};
    for (const key of Object.keys(value)) {
      Object.defineProperty(result, key, {
        value: cloneJson(value[key], label),
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
    return result;
  }
  throw new Error(`${label} is not JSON data`);
}

/**
 * Deep structural equality for JSON values: object keys in any order, arrays in order, no coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether the two values are structurally equal as JSON
 */
function jsonEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return a === b;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    return a.every((item, index) => jsonEqual(item, b[index]));
  }
  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEqual(a[key], b[key]));
  }
  return false;
}

/**
 * Resolve the parent container and final token for a pointer with at least one token.
 *
 * @param {unknown} document the root document
 * @param {string[]} tokens the pointer's tokens
 * @returns {{ parent: unknown, token: string }} the container to mutate and the final token
 */
function resolveParent(document, tokens) {
  let current = document;
  const consumed = [];
  for (let i = 0; i < tokens.length - 1; i += 1) {
    consumed.push(tokens[i]);
    current = stepInto(current, tokens[i], formatPointer(consumed));
  }
  return { parent: current, token: tokens[tokens.length - 1] };
}

/**
 * Remove the value at a pointer from a document (mutating), returning the removed value.
 *
 * @param {unknown} document the root document
 * @param {string} pointer pointer to the value to remove
 * @returns {unknown} the removed value
 */
function removeAt(document, pointer) {
  const tokens = parsePointer(pointer);
  if (tokens.length === 0) throw new PointerError('cannot remove the whole document', pointer);
  const { parent, token } = resolveParent(document, tokens);
  const fullPath = pointer;
  if (Array.isArray(parent)) {
    if (!/^(0|[1-9][0-9]*)$/.test(token)) {
      throw new PointerError(`invalid array index: ${token} at ${fullPath}`, fullPath);
    }
    const index = Number(token);
    if (index >= parent.length) {
      throw new PointerError(`index out of range: ${token} at ${fullPath}`, fullPath);
    }
    const [removed] = parent.splice(index, 1);
    return removed;
  }
  if (parent !== null && typeof parent === 'object') {
    if (!Object.prototype.hasOwnProperty.call(parent, token)) {
      throw new PointerError(`missing property: ${token} at ${fullPath}`, fullPath);
    }
    const removed = parent[token];
    delete parent[token];
    return removed;
  }
  throw new PointerError(`cannot index into ${typeName(parent)} at ${fullPath}`, fullPath);
}

/**
 * Add (or overwrite) a value at a pointer in a document (mutating).
