   * @param {{priority: number, seq: number}} b Right entry.
   * @returns {boolean} True when a comes before b.
   */
  #before(a, b) {
    return a.priority < b.priority || (a.priority === b.priority && a.seq < b.seq);
  }

  /**
   * Places an entry at a slot and records its position.
   * @param {number} at Slot to fill.
   * @param {{key: string, priority: number, seq: number}} item Entry to place.
   * @returns {void}
   */
  #place(at, item) {
    this.#items[at] = item;
    this.#index.set(item.key, at);
  }

  /**
   * Moves an entry towards the root until the heap order holds.
   * @param {number} start Slot to move from.
   * @returns {void}
   */
  #siftUp(start) {
    const item = this.#items[start];
    let at = start;
    while (at > 0) {
      const parent = (at - 1) >> 1;
      if (!this.#before(item, this.#items[parent])) break;
      this.#place(at, this.#items[parent]);
      at = parent;
    }
    this.#place(at, item);
  }

  /**
   * Moves an entry towards the leaves until the heap order holds.
   * @param {number} start Slot to move from.
   * @returns {void}
   */
  #siftDown(start) {
    const item = this.#items[start];
    const count = this.#items.length;
    let at = start;
    for (;;) {
      const left = 2 * at + 1;
      if (left >= count) break;
      const right = left + 1;
      let child = left;
      if (right < count && this.#before(this.#items[right], this.#items[left])) child = right;
      if (!this.#before(this.#items[child], item)) break;
      this.#place(at, this.#items[child]);
      at = child;
    }
    this.#place(at, item);
  }

  /**
   * Restores the heap order around a slot after a priority change.
   * @param {number} at Slot to repair.
   * @returns {void}
   */
  #repair(at) {
    const parent = (at - 1) >> 1;
    if (at > 0 && this.#before(this.#items[at], this.#items[parent])) this.#siftUp(at);
    else this.#siftDown(at);
  }

  /**
   * Removes the entry held in one slot.
   * @param {number} at Slot to clear.
   * @returns {void}
   */
  #removeAt(at) {
    const removed = this.#items[at];
    this.#index.delete(removed.key);
    const last = this.#items.pop();
    if (last !== removed) {
      this.#place(at, last);
      this.#repair(at);
    }
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    checkKey(key);
    checkPriority(priority);
    if (this.#index.has(key)) throw new Error(`duplicate key: "${key}"`);
    this.#seq += 1;
    this.#items.push({ key, priority, seq: this.#seq });
    this.#siftUp(this.#items.length - 1);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    const top = this.#items[0];
    return top === undefined ? undefined : { key: top.key, priority: top.priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    const top = this.#items[0];
    if (top === undefined) return undefined;
    this.#removeAt(0);
    return { key: top.key, priority: top.priority };
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    checkKey(key);
    return this.#index.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    checkKey(key);
    const at = this.#index.get(key);
    return at === undefined ? undefined : this.#items[at].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    checkKey(key);
    checkPriority(priority);
    const at = this.#index.get(key);
    if (at === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    if (priority > this.#items[at].priority) {
      throw new RangeError(`priority must not increase for "${key}"`);
    }
    this.#items[at].priority = priority;
    this.#siftUp(at);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
   * @returns {void}
   */
  setPriority(key, priority) {
    checkKey(key);
    checkPriority(priority);
    const at = this.#index.get(key);
    if (at === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    this.#items[at].priority = priority;
    this.#repair(at);
  }

  /**
   * Removes a held key.
   * @param {string} key Key to remove.
   * @returns {boolean} True when an entry was removed.
   */
  remove(key) {
    checkKey(key);
    const at = this.#index.get(key);
    if (at === undefined) return false;
    this.#removeAt(at);
    return true;
  }

  /**
   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const out = [];
    for (let entry = this.pop(); entry !== undefined; entry = this.pop()) out.push(entry);
    return out;
  }
}
"}

