}","new_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (!isNonEmptyString(command.commandId)) throw new TypeError('command must carry a non-empty commandId');
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    if (this.#commandResults.has(command.commandId)) {
      return { ...this.#commandResults.get(command.commandId), replayed: true };
    }

    const from = this.#state;

    if (command.at < this.#clockMs) {
      const seq = this.#audit.length + 1;
      this.#audit.push({
        seq,
        commandId: command.commandId,
        type: command.type,
        at: this.#clockMs,
        from,
        to: from,
        ok: false,
        code: 'CLOCK_REGRESSION',
      });
      const result = {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: 'command time precedes the order clock',
        state: from,
        seq,
      };
      this.#commandResults.set(command.commandId, result);
      return { ...result, replayed: false };
    }

    this.#clockMs = command.at;

    const finish = (outcome) => {
      const seq = this.#audit.length + 1;
      const to = outcome.ok ? this.#state : from;
      const entry = {
        seq,
        commandId: command.commandId,
        type: command.type,
        at: command.at,
        from,
        to,
        ok: outcome.ok,
      };
      if (!outcome.ok) entry.code = outcome.code;
      this.#audit.push(entry);
      const result = outcome.ok
        ? { ok: true, state: to, seq }
        : { ok: false, code: outcome.code, message: outcome.message, state: to, seq };
      this.#commandResults.set(command.commandId, result);
      return { ...result, replayed: false };
    };

    if (!allowedTypes(from).includes(command.type)) {
      return finish({ ok: false, code: 'BAD_STATE', message: `${command.type} is not allowed in state ${from}` });
    }

    const fieldError = this.#checkFields(command);
    if (fieldError) return finish({ ok: false, ...fieldError });

    const businessError = this.#checkBusiness(command);
    if (businessError) return finish({ ok: false, ...businessError });

    this.#applyEffect(command);
    return finish({ ok: true });
  }

  #checkFields(command) {
    const strings = REQUIRED_STRING_FIELDS[command.type] || [];
    for (const field of strings) {
      if (!isNonEmptyString(command[field])) {
        return { code: 'MISSING_FIELD', message: `${command.type} requires a non-empty ${field}` };
      }
    }
    if (command.type === 'addItem') {
      if (!Number.isInteger(command.qty) || command.qty < 1) {
        return { code: 'BAD_AMOUNT', message: 'qty must be an integer of at least 1' };
      }
      if (!Number.isInteger(command.unitPriceCents) || command.unitPriceCents < 0) {
        return { code: 'BAD_AMOUNT', message: 'unitPriceCents must be a non-negative integer' };
      }
    }
    if (command.type === 'pay') {
      if (!Number.isInteger(command.amountCents) || command.amountCents < 0) {
        return { code: 'BAD_AMOUNT', message: 'amountCents must be a non-negative integer' };
      }
    }
    if (command.type === 'refund') {
      if (!Number.isInteger(command.amountCents) || command.amountCents < 1) {
        return { code: 'BAD_AMOUNT', message: 'amountCents must be an integer of at least 1' };
      }
    }
    return null;
  }

  #checkBusiness(command) {
    if (command.type === 'addItem') {
      if (this.#items.has(command.sku)) {
        return { code: 'DUPLICATE_SKU', message: `sku ${command.sku} is already present` };
      }
    }
    if (command.type === 'removeItem') {
      if (!this.#items.has(command.sku)) {
        return { code: 'NO_SUCH_ITEM', message: `sku ${command.sku} is not present` };
      }
    }
    if (command.type === 'pay') {
      if (this.#items.size === 0) {
        return { code: 'EMPTY_ORDER', message: 'cannot pay an order with no items' };
      }
      if (command.amountCents !== this.totalCents) {
        return { code: 'AMOUNT_MISMATCH', message: 'amountCents does not match the order total' };
      }
    }
    if (command.type === 'refund') {
      if (command.amountCents > this.#paidCents - this.#refundedCents) {
        return { code: 'REFUND_TOO_LARGE', message: 'amountCents exceeds the outstanding payment' };
      }
    }
    return null;
  }

  #applyEffect(command) {
    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        break;
      case 'removeItem':
        this.#items.delete(command.sku);
        break;
      case 'pay':
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        break;
      case 'pack':
        this.#state = 'packed';
        break;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents >= this.#paidCents) {
          this.#refundedCents = this.#paidCents;
          this.#state = 'refunded';
        }
        break;
      default:
        break;
    }
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
