    }

    const from = this.#state;

    if (command.at < this.#clockMs) {
      const seq = this.#audit.length + 1;
      this.#audit.push({
        seq,
        commandId: command.commandId,
        type: command.type,
        at: this.#clockMs,
        from,
        to: from,
        ok: false,
        code: 'CLOCK_REGRESSION',
      });
      const result = {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: 'command time precedes the order clock',
        state: from,
        seq,
      };
      this.#commandResults.set(command.commandId, result);
      return { ...result, replayed: false };
    }

    this.#clockMs = command.at;

    const finish = (outcome) => {
      const seq = this.#audit.length + 1;
      const to = outcome.ok ? this.#state : from;
      const entry = {
        seq,
        commandId: command.commandId,
        type: command.type,
        at: command.at,
        from,
        to,
        ok: outcome.ok,
      };
      if (!outcome.ok) entry.code = outcome.code;
      this.#audit.push(entry);
      const result = outcome.ok
        ? { ok: true, state: to, seq }
        : { ok: false, code: outcome.code, message: outcome.message, state: to, seq };
      this.#commandResults.set(command.commandId, result);
      return { ...result, replayed: false };
    };

    if (!allowedTypes(from).includes(command.type)) {
      return finish({ ok: false, code: 'BAD_STATE', message: `${command.type} is not allowed in state ${from}` });
    }

    const fieldError = this.#checkFields(command);
    if (fieldError) return finish({ ok: false, ...fieldError });

    const businessError = this.#checkBusiness(command);
    if (businessError) return finish({ ok: false, ...businessError });

    this.#applyEffect(command);
    return finish({ ok: true });
  }

  #checkFields(command) {
    const strings = REQUIRED_STRING_FIELDS[command.type] || [];
    for (const field of strings) {
      if (!isNonEmptyString(command[field])) {
        return { code: 'MISSING_FIELD', message: `${command.type} requires a non-empty ${field}` };
