      if (!Number.isInteger(command.amountCents) || command.amountCents < 0) {
        return { code: 'BAD_AMOUNT', message: 'amountCents must be a non-negative integer' };
      }
    }
    if (command.type === 'refund') {
      if (!Number.isInteger(command.amountCents) || command.amountCents < 1) {
        return { code: 'BAD_AMOUNT', message: 'amountCents must be an integer of at least 1' };
      }
    }
    return null;
  }

  #checkBusiness(command) {
    if (command.type === 'addItem') {
      if (this.#items.has(command.sku)) {
        return { code: 'DUPLICATE_SKU', message: `sku ${command.sku} is already present` };
      }
    }
    if (command.type === 'removeItem') {
      if (!this.#items.has(command.sku)) {
        return { code: 'NO_SUCH_ITEM', message: `sku ${command.sku} is not present` };
      }
    }
    if (command.type === 'pay') {
      if (this.#items.size === 0) {
        return { code: 'EMPTY_ORDER', message: 'cannot pay an order with no items' };
      }
      if (command.amountCents !== this.totalCents) {
        return { code: 'AMOUNT_MISMATCH', message: 'amountCents does not match the order total' };
      }
    }
    if (command.type === 'refund') {
      if (command.amountCents > this.#paidCents - this.#refundedCents) {
        return { code: 'REFUND_TOO_LARGE', message: 'amountCents exceeds the outstanding payment' };
      }
    }
    return null;
  }

  #applyEffect(command) {
    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        break;
      case 'removeItem':
        this.#items.delete(command.sku);
        break;
      case 'pay':
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        break;
      case 'pack':
        this.#state = 'packed';
        break;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents >= this.#paidCents) {
          this.#refundedCents = this.#paidCents;
          this.#state = 'refunded';
        }
        break;
      default:
        break;
    }
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}"}

