  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Business-level guards specific to a command's type.
   *
   * @param {string} type Command type.
   * @param {object} command Command being applied.
   * @returns {{code: string, message: string}|null} A failure, or null when the guards pass.
   */
  #checkBusiness(type, command) {
    switch (type) {
      case 'addItem':
        if (this.#items.has(command.sku)) {
          return { code: 'DUPLICATE_SKU', message: `sku ${command.sku} is already present` };
        }
        return null;
      case 'removeItem':
        if (!this.#items.has(command.sku)) {
          return { code: 'NO_SUCH_ITEM', message: `sku ${command.sku} is not present` };
        }
        return null;
      case 'pay':
        if (this.#items.size === 0) {
          return { code: 'EMPTY_ORDER', message: 'an order with no items cannot be paid' };
        }
        if (command.amountCents !== this.totalCents) {
          return { code: 'AMOUNT_MISMATCH', message: 'payment amount does not match the order total' };
        }
        return null;
      case 'refund':
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return { code: 'REFUND_TOO_LARGE', message: 'refund amount exceeds what remains to be refunded' };
        }
        return null;
      default:
        return null;
    }
  }

  /**
   * Apply a command's effect once every guard has passed.
   *
   * @param {string} type Command type.
   * @param {object} command Command being applied.
   * @returns {string} The resulting state.
   */
  #performEffect(type, command) {
    switch (type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        this.#state = 'created';
        break;
      case 'removeItem':
        this.#items.delete(command.sku);
        this.#state = 'created';
        break;
      case 'pay':
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        break;
      case 'pack':
        this.#state = 'packed';
        break;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents === this.#paidCents) this.#state = 'refunded';
        break;
      default:
        break;
    }
    return this.#state;
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    const { type, commandId, at } = command;
    if (!COMMAND_TYPES.includes(type)) throw new TypeError(`unknown command type: ${type}`);
    if (typeof commandId !== 'string' || commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(at) || at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    if (this.#commandResults.has(commandId)) {
      return { ...this.#commandResults.get(commandId), replayed: true };
    }

    const from = this.#state;

    const record = (auditAt, to, ok, code, message) => {
      const seq = this.#audit.length + 1;
      const entry = { seq, commandId, type, at: auditAt, from, to, ok };
      if (!ok) entry.code = code;
      this.#audit.push(entry);
      const result = ok ? { ok: true, state: to, seq } : { ok: false, code, message, state: to, seq };
      this.#commandResults.set(commandId, result);
      return { ...result, replayed: false };
    };

    if (at < this.#clockMs) {
      return record(this.#clockMs, from, false, 'CLOCK_REGRESSION', 'command time precedes the order clock');
    }

    this.#clockMs = at;

    if (!allowedTypes(from).includes(type)) {
      return record(at, from, false, 'BAD_STATE', `${type} is not allowed in state ${from}`);
    }

    const fieldError = validateFields(type, command);
    if (fieldError) {
      return record(at, from, false, fieldError.code, fieldError.message);
    }

    const businessError = this.#checkBusiness(type, command);
    if (businessError) {
      return record(at, from, false, businessError.code, businessError.message);
    }

    const to = this.#performEffect(type, command);
    return record(at, to, true);
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}
"}

