{"file_path":"src/resolve.js","old_string":"export function resolve(registry, rootDeps) {
  throw new Error('not implemented');
}","new_string":"export function resolve(registry, rootDeps) {
  if (!isObject(registry)) throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  for (const [name, entry] of Object.entries(registry)) {
    if (!isObject(entry)) throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    for (const [version, metadata] of Object.entries(entry)) {
      parseVersion(version);
      if (!isObject(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${version}`);
      }
      const deps = metadata.deps;
      if (deps !== undefined) {
        if (!isObject(deps)) {
          throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${version} must be an object`);
        }
        for (const range of Object.values(deps)) parseRange(range);
      }
    }
  }
  if (!isObject(rootDeps)) throw new ResolveError('BAD_DEPENDENCIES', 'root dependencies must be an object');
  for (const range of Object.values(rootDeps)) parseRange(range);

  /** @type {Map<string, Array<{range: string, via: string}>>} */
  const constraints = new Map();
  /** @type {Set<string>} */
  const pending = new Set();
  /** @type {Map<string, string>} */
  const selected = new Map();
  /** @type {Map<string, string>} */
  const chains = new Map();
  const order = [];

  const addConstraint = (name, range, via) => {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push({ range, via });
  };

  const fail = (name) => {
    const available = Object.keys(registry[name] ?? {}).sort((a, b) => (a === b ? 0 : satisfies(a, `<${b}`) ? -1 : 1));
    throw new ConflictError(name, constraints.get(name) ?? [], available);
  };

  for (const name of Object.keys(rootDeps).sort()) {
    addConstraint(name, rootDeps[name], '<root>');
    pending.add(name);
  }

  while (pending.size > 0) {
    const name = [...pending].sort()[0];
    pending.delete(name);
    if (!Object.prototype.hasOwnProperty.call(registry, name)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }
    const list = constraints.get(name) ?? [];
    let candidates = Object.keys(registry[name]);
    for (const entry of list) candidates = candidates.filter((version) => satisfies(version, entry.range));
    const chosen = maxSatisfying(candidates, '*');
    if (chosen === null) fail(name);
    selected.set(name, chosen);
    order.push(name);
    const chain = `${list.length > 0 ? list[0].via : '<root>'} > ${name}@${chosen}`;
    chains.set(name, chain);
    const deps = registry[name][chosen].deps ?? {};
    for (const dep of Object.keys(deps).sort()) {
      addConstraint(dep, deps[dep], chain);
      if (selected.has(dep)) {
        if (!satisfies(selected.get(dep), deps[dep])) fail(dep);
      } else {
        pending.add(dep);
      }
    }
  }

  const resolved = {};
  for (const name of [...selected.keys()].sort()) resolved[name] = selected.get(name);
  return { resolved, order };
}"}

