}","new_string":"export function resolve(registry, rootDeps) {
  const validRegistry = validateRegistry(registry);
  const validRootDeps = validateRootDeps(rootDeps);

  const constraints = new Map();
  const pendingSet = new Set();
  const selected = new Map();
  const order = [];

  function addConstraint(name, range, via) {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push({ range, via });
    if (!selected.has(name)) pendingSet.add(name);
  }

  for (const name of Object.keys(validRootDeps).sort()) {
    addConstraint(name, validRootDeps[name], '<root>');
  }

  while (pendingSet.size > 0) {
    const name = [...pendingSet].sort()[0];
    pendingSet.delete(name);
    if (!Object.prototype.hasOwnProperty.call(validRegistry, name)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }
    const versions = Object.keys(validRegistry[name]).sort(compareVersions);
    const cons = constraints.get(name) ?? [];
    let candidate = null;
    for (const version of versions) {
      if (cons.every((entry) => satisfies(version, entry.range))) {
        if (candidate === null || compareVersions(version, candidate) > 0) candidate = version;
      }
    }
    if (candidate === null) {
      throw new ConflictError(name, cons, versions);
    }
    selected.set(name, candidate);
    order.push(name);
    const chain = `${cons[0].via} > ${name}@${candidate}`;
    const deps = validRegistry[name][candidate].deps ?? {};
    for (const depName of Object.keys(deps).sort()) {
      const range = deps[depName];
      addConstraint(depName, range, chain);
      if (selected.has(depName) && !satisfies(selected.get(depName), range)) {
        const depVersions = Object.keys(validRegistry[depName] ?? {}).sort(compareVersions);
        throw new ConflictError(depName, constraints.get(depName), depVersions);
      }
    }
  }

  const resolved = {};
  for (const name of [...selected.keys()].sort()) resolved[name] = selected.get(name);
  return { resolved, order };
}"}

